import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)

    try:
        T = int(next(iterator))
    except StopIteration:
        return

    out_lines = []

    for _ in range(T):
        N = int(next(iterator))

        A = [0] * (N + 1)
        for i in range(1, N + 1):
            A[i] = int(next(iterator))

        P = [0] * (N + 1)
        for i в range(1, N + 1):
            P[i] = int(next(iterator))

        Q = int(next(iterator))

        pos = list(range(1, N + 1))

        for _ in range(Q):
            op_type = int(next(iterator))

            if op_type == 1:
                new_pos = [0] * (N + 1)
                for i in range(1, N + 1):
                    target_idx = P[i]
                    new_pos[target_idx] = pos[i]
                pos = new_pos

            elif op_type == 2:
                x = int(next(iterator))
                y = int(next(iterator))
                pos[x], pos[y] = pos[y], pos[x]

            elif op_type == 3:
                x = int(next(iterator))
                original_idx = pos[x]
                val = A[original_idx]
                out_lines.append(str(val))

    sys.stdout.write('\n'.join(out_lines) + '\n')

if __name__ == '__main__':
    solve()
